import {readRecords,writeRecords,searchRecords,recordURL} from './records.mjs';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
let kind='work',timer;
function toast(text){$('toast').textContent=text;clearTimeout(timer);timer=setTimeout(()=>$('toast').textContent='',4000);}
function all(){return ['work','date'].flatMap(kind=>readRecords(kind).map(record=>({record,kind})));}
function render(){const list=$('memory-list');list.replaceChildren();$('storage-error').textContent='';document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===kind)));let records;try{records=all();}catch{$('storage-error').textContent='無法讀取本機紀錄，請檢查儲存權限。原始資料未被修改。';$('memory-count').textContent='';return;}
 const filtered=records.filter(x=>kind==='all'||x.kind===kind).filter(x=>searchRecords([x.record],$('search').value).length).sort((a,b)=>(b.record.savedAt||'').localeCompare(a.record.savedAt||''));$('memory-count').textContent=`${filtered.length} 筆紀錄`;
 if(!filtered.length)list.append(el('p',$('search').value?'找不到符合的紀錄。':'尚無工程紀錄。可匯入舊檔案，或在計算器儲存新紀錄。','memory-empty'));
 for(const {record:r,kind:k}of filtered){const card=el('details','','memory-item'),summary=el('summary',''),heading=el('div','');heading.append(el('h2',r.name||'未命名紀錄'),el('p',`${r.start} ／ ${r.end}`));summary.append(heading,el('strong',r.result));card.append(summary);const body=el('div','','memory-body');body.append(el('p',r.detail));if(r.savedAt){const d=new Date(r.savedAt);if(Number.isFinite(+d))body.append(el('p','儲存：'+d.toLocaleString('zh-TW')));}
 if(r.options){const fields=[['saturday','星期六'],['sunday','星期日'],['holidays','2026 國定假日']];body.append(el('p','排除：'+(fields.filter(([field])=>r.options[field]).map(([,name])=>name).join('、')||'無')));}
 if(r.snapshot){for(const [field,label]of (k==='work'?[['calendar','日曆天數'],['working','工作天數'],['excluded','排除天數']]:[['days','相隔天數'],['inclusive','含頭含尾']]))if(Number.isFinite(r.snapshot[field])){const line=el('div','','detail-line');line.append(el('span',label),el('b',r.snapshot[field]+' 天'));body.append(line);}}
 if(k==='work'&&!r.options)body.append(el('p','舊紀錄未保存完整排除設定，載回後請重新選擇。'));
 const form=el('form','','rename-form'),label=el('label','工程／事項名稱'),input=document.createElement('input');input.type='text';input.maxLength=120;input.value=r.name||'';label.append(input);const rename=el('button','儲存名稱');rename.type='submit';form.append(label,rename);form.onsubmit=e=>{e.preventDefault();try{writeRecords(k,readRecords(k).map(x=>x.id===r.id?{...x,name:input.value.trim()}:x));render();toast('名稱已更新');}catch{toast('名稱無法儲存，原紀錄未變更。');}};body.append(form);
 const actions=el('div','','memory-actions'),load=el('a',k==='work'&&!r.options?'載回並重設條件':'載回計算器','load-record');load.href=recordURL(r,k);const remove=el('button','刪除此紀錄','delete-record');remove.type='button';remove.onclick=()=>{if(!confirm(`刪除「${r.name||'未命名紀錄'}」？`))return;try{writeRecords(k,readRecords(k).filter(x=>x.id!==r.id));render();}catch{toast('無法刪除，請檢查儲存權限。');}};actions.append(load,remove);body.append(actions);card.append(body);list.append(card);}
}
$('search').addEventListener('input',render);document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;render();});window.addEventListener('storage',render);
$('export').onclick=()=>{try{const data={version:2,exportedAt:new Date().toISOString(),work:readRecords('work'),date:readRecords('date')};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`工程工期紀錄-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('無法匯出，請檢查本機紀錄。');}};
render();
$('import-records').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('檔案超過 5 MB');const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.work)||!Array.isArray(data.date))throw new Error('請選擇由工程紀錄匯出的 JSON 檔案');const {validRecord}=await import('./records.mjs');const {parseDate}=await import('./date-core.mjs');for(const kind of ['work','date'])for(const r of data[kind]){if(!validRecord(r))throw new Error('紀錄欄位不完整');parseDate(r.start);parseDate(r.end);if(r.options&&['saturday','sunday','holidays'].some(k=>typeof r.options[k]!=='boolean'))throw new Error('排除設定格式不正確');}let count=0;const prepared={};for(const kind of ['work','date']){const old=readRecords(kind),ids=new Set(old.map(r=>r.id));const added=data[kind].filter(r=>{if(ids.has(r.id))return false;ids.add(r.id);return true;});prepared[kind]=[...added,...old];count+=added.length;}const before={work:localStorage.getItem('daybetween-work-v1'),date:localStorage.getItem('daybetween-date-v1')};try{writeRecords('work',prepared.work);writeRecords('date',prepared.date);}catch(error){for(const kind of ['work','date']){const key=`daybetween-${kind}-v1`;if(before[kind]===null)localStorage.removeItem(key);else localStorage.setItem(key,before[kind]);}throw error;}render();toast(`已匯入 ${count} 筆紀錄，重複項目已略過。`);}catch(error){toast('匯入失敗：'+error.message);}finally{event.target.value='';}});

$('open-import').onclick=()=>$('import-records').click();
